#!/usr/bin/env python3
"""
Markdown to HTML converter with Highlight.js syntax highlighting.

Converts a markdown file to HTML with:
- Automatic language detection for code blocks
- Highlight.js syntax highlighting (colored)
- Smart text/diagram detection (plain monochrome)
- Professional styling
- GitHub Light theme

Usage:
    python md-to-html-converter.py input.md output.html
    python md-to-html-converter.py input.md  # Creates input.html
"""

import re
import subprocess
import sys
from pathlib import Path


def add_language_specs(content):
    """Add language specifications to unlabeled code blocks."""
    parts = re.split(r'(```.*?```)', content, flags=re.DOTALL)

    result = []

    for i, part in enumerate(parts):
        if part.startswith('```'):
            match = re.match(r'```(\w*)\n(.*)\n```', part, re.DOTALL)
            if match:
                lang = match.group(1)
                code = match.group(2)

                # If no language specified, detect from content
                if not lang:
                    # Diagrams/ASCII art indicators
                    diagram_chars = ['┌', '├', '└', '─', '│', '↓', '→', '⇄', '⇒', '═', '║']
                    diagram_keywords = ['Cron', 'Load', 'Evaluate', 'Execute', 'Update',
                                       'Phase', 'Step', 'GET', 'POST', 'server', 'database']

                    if any(char in code for char in diagram_chars):
                        lang = 'text'
                    elif any(keyword in code for keyword in diagram_keywords):
                        lang = 'text'
                    elif '-->' in code or '↓' in code or '├─' in code:
                        lang = 'text'
                    else:
                        lang = 'text'  # Default to text for unlabeled

                part = f'```{lang}\n{code}\n```'

        result.append(part)

    return ''.join(result)


def generate_html_with_pandoc(md_file, html_file):
    """Generate HTML from markdown using pandoc."""
    try:
        subprocess.run(
            ['pandoc', str(md_file), '-t', 'html', '--standalone',
             '--syntax-highlighting=none', '-o', str(html_file)],
            check=True,
            capture_output=True
        )
        print(f"✓ Generated HTML with pandoc: {html_file}")
    except subprocess.CalledProcessError as e:
        print(f"✗ Pandoc error: {e.stderr.decode()}")
        sys.exit(1)
    except FileNotFoundError:
        print("✗ Pandoc not found. Install with: brew install pandoc")
        sys.exit(1)


def add_highlightjs(html_content):
    """Add Highlight.js CSS and JavaScript."""
    highlightjs_css = '''    <!-- Highlight.js CSS (GitHub Light theme) -->
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js"></script>'''

    head_insert_pos = html_content.find('</head>')
    if head_insert_pos > 0:
        html_content = (html_content[:head_insert_pos] + highlightjs_css + '\n' +
                       html_content[head_insert_pos:])

    return html_content


def add_custom_css(html_content):
    """Add custom CSS styling."""
    custom_css = '''    <style>
        code {
            background-color: #f6f8fa;
            padding: 2px 6px;
            border-radius: 3px;
            font-size: 0.95em;
        }

        pre {
            background-color: #f6f8fa;
            border: 1px solid #e1e4e8;
            border-left: 4px solid #0366d6;
            padding: 16px;
            border-radius: 6px;
            overflow-x: auto;
            line-height: 1.6;
            margin: 1.5em 0;
        }

        pre code {
            background-color: transparent;
            padding: 0;
            border-radius: 0;
            color: #24292e;
        }

        .hljs {
            background: #f6f8fa;
            color: #24292e;
        }

        h1 {
            border-bottom: 3px solid #2c3e50;
            padding-bottom: 10px;
        }

        h2 {
            border-left: 5px solid #0366d6;
            padding-left: 10px;
            color: #2c3e50;
        }

        body {
            max-width: 900px;
            margin: 0 auto;
            padding: 2rem;
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
        }

        @media print {
            h1, h2, h3, h4 {
                page-break-after: avoid;
            }
            pre {
                page-break-inside: avoid;
            }
        }
    </style>'''

    head_insert_pos = html_content.find('</head>')
    if head_insert_pos > 0:
        html_content = (html_content[:head_insert_pos] + custom_css + '\n' +
                       html_content[head_insert_pos:])

    return html_content


def fix_code_classes(html_content):
    """Fix class placement for Highlight.js detection."""
    # Move class from <pre> to <code> and add language- prefix
    html_content = re.sub(
        r'<pre class="(\w+)"><code>',
        r'<pre><code class="language-\1">',
        html_content
    )

    # Handle existing classes on code
    html_content = re.sub(
        r'<code class="(\w+)">',
        r'<code class="language-\1">',
        html_content
    )

    return html_content


def add_highlight_initialization(html_content):
    """Add Highlight.js initialization script."""
    init_script = '''    <script>
        document.addEventListener('DOMContentLoaded', function() {
            document.querySelectorAll('pre code').forEach((block) => {
                const lang = block.className;

                // Highlight for: python, json, bash, dockerfile, yaml, toml, shell
                const highlightable = ['python', 'json', 'bash', 'dockerfile', 'yaml', 'toml', 'shell'];
                const shouldHighlight = highlightable.some(lang_type => lang.includes(lang_type));

                if (shouldHighlight) {
                    hljs.highlightElement(block);
                }
                // text, plaintext, ascii blocks remain plain monochrome
            });
        });
    </script>'''

    body_end_pos = html_content.find('</body>')
    if body_end_pos > 0:
        html_content = (html_content[:body_end_pos] + init_script + '\n' +
                       html_content[body_end_pos:])

    return html_content


def process_markdown(input_md, output_html=None):
    """Main conversion process."""
    input_path = Path(input_md)

    if not input_path.exists():
        print(f"✗ Input file not found: {input_md}")
        sys.exit(1)

    # Determine output filename
    if output_html is None:
        output_html = input_path.stem + '.html'

    output_path = Path(output_html)

    print(f"📖 Processing: {input_md}")

    # Step 1: Add language specifications to markdown
    print("  1. Adding language specifications to code blocks...")
    with open(input_path, 'r', encoding='utf-8') as f:
        content = f.read()

    content = add_language_specs(content)

    # Write updated markdown temporarily
    temp_md = input_path.parent / '.temp_md_converted.md'
    with open(temp_md, 'w', encoding='utf-8') as f:
        f.write(content)

    # Step 2: Generate HTML with pandoc
    print("  2. Generating HTML with pandoc...")
    generate_html_with_pandoc(temp_md, output_path)

    # Step 3: Read generated HTML
    print("  3. Enhancing HTML...")
    with open(output_path, 'r', encoding='utf-8') as f:
        html = f.read()

    # Step 4: Add enhancements
    html = add_highlightjs(html)
    html = add_custom_css(html)
    html = fix_code_classes(html)
    html = add_highlight_initialization(html)

    # Step 5: Write final HTML
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(html)

    # Cleanup
    temp_md.unlink()

    # Statistics
    with open(output_path, 'r', encoding='utf-8') as f:
        final_html = f.read()

    python_count = len(re.findall(r'class="language-python"', final_html))
    json_count = len(re.findall(r'class="language-json"', final_html))
    text_count = len(re.findall(r'class="language-text"', final_html))
    bash_count = len(re.findall(r'class="language-bash"', final_html))

    file_size = output_path.stat().st_size / 1024

    print(f"\n✓ Conversion complete!")
    print(f"  Output: {output_html} ({file_size:.1f} KB)")
    print(f"\n  Code blocks:")
    print(f"    Python:  {python_count}")
    print(f"    JSON:    {json_count}")
    print(f"    Bash:    {bash_count}")
    print(f"    Text:    {text_count} (diagrams, ASCII art)")
    print(f"\n  Features:")
    print(f"    ✓ Syntax highlighting (Highlight.js)")
    print(f"    ✓ GitHub Light theme (white background)")
    print(f"    ✓ Professional styling")
    print(f"    ✓ Responsive design")
    print(f"    ✓ Print-optimized")


def main():
    """CLI entry point."""
    if len(sys.argv) < 2:
        print("Usage: python md-to-html-converter.py <input.md> [output.html]")
        print("\nExample:")
        print("  python md-to-html-converter.py README.md")
        print("  python md-to-html-converter.py docs.md output.html")
        sys.exit(1)

    input_md = sys.argv[1]
    output_html = sys.argv[2] if len(sys.argv) > 2 else None

    process_markdown(input_md, output_html)


if __name__ == '__main__':
    main()

