            background: #f6f8fa;
            color: #24292e;
        }

        h1 {
            border-bottom: 3px solid #2c3e50;
            padding-bottom: 10px;
        }

        h2 {
            border-left: 5px solid #0366d6;
            padding-left: 10px;
            color: #2c3e50;
        }

