    head_insert_pos = html_content.find('</head>')
    if head_insert_pos > 0:
        html_content = (html_content[:head_insert_pos] + custom_css + '\n' +
                       html_content[head_insert_pos:])

    return html_content


def fix_code_classes(html_content):
    """Fix class placement for Highlight.js detection."""
    # Move class from <pre> to <code> and add language- prefix
    html_content = re.sub(
        r'<pre class="(\w+)"><code>',
        r'<pre><code class="language-\1">',
        html_content
    )

    # Handle existing classes on code
    html_content = re.sub(
        r'<code class="(\w+)">',
        r'<code class="language-\1">',
        html_content
    )

    return html_content


def add_highlight_initialization(html_content):
    """Add Highlight.js initialization script."""
    init_script = '''    <script>
        document.addEventListener('DOMContentLoaded', function() {
            document.querySelectorAll('pre code').forEach((block) => {
                const lang = block.className;

                // Highlight for: python, json, bash, dockerfile, yaml, toml, shell
